#include "sqlite_repository.hpp"
#include "migrations.hpp"
#include "transaction.hpp"
#include <limits>
#include <stdexcept>
namespace exotic::autonomy::persistence { namespace {
std::int64_t sid(std::uint64_t v){if(v>static_cast<std::uint64_t>((std::numeric_limits<std::int64_t>::max)()))throw DatabaseError("identifier exceeds SQLite range");return static_cast<std::int64_t>(v);}TimePoint opt_time(const Statement&s,int c){return s.column_is_null(c)?TimePoint{}:from_unix_milliseconds(s.column_int64(c));}
}
SqliteAutonomyRepository::SqliteAutonomyRepository(const std::filesystem::path&p):database_(p){MigrationRunner::migrate(database_);}
ObjectiveId SqliteAutonomyRepository::next_objective_id() { return static_cast<ObjectiveId>(database_.next_sequence("autonomy.objectives")); }ProposalId SqliteAutonomyRepository::next_proposal_id() { return static_cast<ProposalId>(database_.next_sequence("autonomy.proposals")); }OperationId SqliteAutonomyRepository::next_operation_id() { return static_cast<OperationId>(database_.next_sequence("autonomy.operations")); }AuditEventId SqliteAutonomyRepository::next_audit_event_id() { return static_cast<AuditEventId>(database_.next_sequence("autonomy.audit_events")); }
void SqliteAutonomyRepository::save_objective(const Objective&o){Transaction tx{database_};Statement s{database_,"INSERT INTO objectives(id,title,desired_outcome,priority,status,created_at_ms)VALUES(?,?,?,?,?,?)ON CONFLICT(id)DO UPDATE SET title=excluded.title,desired_outcome=excluded.desired_outcome,priority=excluded.priority,status=excluded.status,created_at_ms=excluded.created_at_ms;"};s.bind(1,sid(o.id));s.bind(2,o.title);s.bind(3,o.desired_outcome);s.bind(4,to_string(o.priority));s.bind(5,to_string(o.status));s.bind(6,to_unix_milliseconds(o.created_at));s.execute();for(auto table:{"objective_metrics","objective_constraints","objective_dependencies"}){Statement d{database_,std::string{"DELETE FROM "}+table+" WHERE objective_id=?;"};d.bind(1,sid(o.id));d.execute();}for(std::size_t i=0;i<o.success_metrics.size();++i){Statement r{database_,"INSERT INTO objective_metrics(objective_id,position,name,target_value,unit)VALUES(?,?,?,?,?);"};r.bind(1,sid(o.id));r.bind(2,static_cast<std::int64_t>(i));r.bind(3,o.success_metrics[i].name);r.bind(4,o.success_metrics[i].target_value);r.bind(5,o.success_metrics[i].unit);r.execute();}for(std::size_t i=0;i<o.constraints.size();++i){Statement r{database_,"INSERT INTO objective_constraints(objective_id,position,value)VALUES(?,?,?);"};r.bind(1,sid(o.id));r.bind(2,static_cast<std::int64_t>(i));r.bind(3,o.constraints[i]);r.execute();}for(auto id:o.dependencies){Statement r{database_,"INSERT INTO objective_dependencies(objective_id,dependency_id)VALUES(?,?);"};r.bind(1,sid(o.id));r.bind(2,sid(id));r.execute();}tx.commit();}
void SqliteAutonomyRepository::save_proposal(const Proposal&p){Transaction tx{database_};Statement s{database_,"INSERT INTO proposals(id,objective_id,proposed_by,plan_name,risk,estimated_usd,estimated_compute_seconds,estimated_duration_seconds,expected_value,confidence,human_approval_required,status,created_at_ms)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)ON CONFLICT(id)DO UPDATE SET objective_id=excluded.objective_id,proposed_by=excluded.proposed_by,plan_name=excluded.plan_name,risk=excluded.risk,estimated_usd=excluded.estimated_usd,estimated_compute_seconds=excluded.estimated_compute_seconds,estimated_duration_seconds=excluded.estimated_duration_seconds,expected_value=excluded.expected_value,confidence=excluded.confidence,human_approval_required=excluded.human_approval_required,status=excluded.status,created_at_ms=excluded.created_at_ms;"};std::size_t i=1;s.bind(i++,sid(p.id));s.bind(i++,sid(p.objective_id));s.bind(i++,p.proposed_by);s.bind(i++,p.plan.name);s.bind(i++,to_string(p.risk));s.bind(i++,p.cost.estimated_usd);s.bind(i++,p.cost.estimated_compute_seconds);s.bind(i++,p.cost.estimated_duration_seconds);s.bind(i++,p.expected_value);s.bind(i++,p.confidence);s.bind(i++,static_cast<std::int64_t>(p.human_approval_required));s.bind(i++,to_string(p.status));s.bind(i++,to_unix_milliseconds(p.created_at));s.execute();Statement d{database_,"DELETE FROM proposal_steps WHERE proposal_id=?;"};d.bind(1,sid(p.id));d.execute();for(std::size_t n=0;n<p.plan.steps.size();++n){auto&step=p.plan.steps[n];Statement r{database_,"INSERT INTO proposal_steps(proposal_id,position,name,description,reversible)VALUES(?,?,?,?,?);"};r.bind(1,sid(p.id));r.bind(2,static_cast<std::int64_t>(n));r.bind(3,step.name);r.bind(4,step.description);r.bind(5,static_cast<std::int64_t>(step.reversible));r.execute();}tx.commit();}
void SqliteAutonomyRepository::save_operation(const OperationRecord&o){Transaction tx{database_};Statement s{database_,"INSERT INTO operations(id,objective_id,proposal_id,agent_id,status,created_at_ms,started_at_ms,completed_at_ms,verification_passed,verification_confidence,failure_reason)VALUES(?,?,?,?,?,?,?,?,?,?,?)ON CONFLICT(id)DO UPDATE SET objective_id=excluded.objective_id,proposal_id=excluded.proposal_id,agent_id=excluded.agent_id,status=excluded.status,created_at_ms=excluded.created_at_ms,started_at_ms=excluded.started_at_ms,completed_at_ms=excluded.completed_at_ms,verification_passed=excluded.verification_passed,verification_confidence=excluded.verification_confidence,failure_reason=excluded.failure_reason;"};std::size_t i=1;s.bind(i++,sid(o.id));s.bind(i++,sid(o.objective_id));s.bind(i++,sid(o.proposal_id));s.bind(i++,o.agent_id);s.bind(i++,to_string(o.status));s.bind(i++,to_unix_milliseconds(o.created_at));if(o.started_at==TimePoint{})s.bind_null(i++);else s.bind(i++,to_unix_milliseconds(o.started_at));if(o.completed_at==TimePoint{})s.bind_null(i++);else s.bind(i++,to_unix_milliseconds(o.completed_at));s.bind(i++,static_cast<std::int64_t>(o.verification.passed));s.bind(i++,o.verification.confidence);s.bind(i++,o.failure_reason);s.execute();for(auto table:{"execution_traces","verification_findings","verification_corrections"}){Statement d{database_,std::string{"DELETE FROM "}+table+" WHERE operation_id=?;"};d.bind(1,sid(o.id));d.execute();}for(std::size_t n=0;n<o.execution_trace.size();++n){Statement r{database_,"INSERT INTO execution_traces(operation_id,position,message,created_at_ms)VALUES(?,?,?,?);"};r.bind(1,sid(o.id));r.bind(2,static_cast<std::int64_t>(n));r.bind(3,o.execution_trace[n]);r.bind(4,to_unix_milliseconds(Clock::now()));r.execute();}for(std::size_t n=0;n<o.verification.findings.size();++n){Statement r{database_,"INSERT INTO verification_findings(operation_id,position,message)VALUES(?,?,?);"};r.bind(1,sid(o.id));r.bind(2,static_cast<std::int64_t>(n));r.bind(3,o.verification.findings[n]);r.execute();}for(std::size_t n=0;n<o.verification.corrections.size();++n){Statement r{database_,"INSERT INTO verification_corrections(operation_id,position,message)VALUES(?,?,?);"};r.bind(1,sid(o.id));r.bind(2,static_cast<std::int64_t>(n));r.bind(3,o.verification.corrections[n]);r.execute();}tx.commit();}
void SqliteAutonomyRepository::append_audit_event(const AuditEvent&e){Statement s{database_,"INSERT INTO audit_events(id,event_type,entity_type,entity_id,actor,message,metadata_json,created_at_ms)VALUES(?,?,?,?,?,?,?,?);"};s.bind(1,sid(e.id));s.bind(2,e.event_type);s.bind(3,e.entity_type);s.bind(4,sid(e.entity_id));s.bind(5,e.actor);s.bind(6,e.message);s.bind(7,e.metadata_json);s.bind(8,to_unix_milliseconds(e.created_at));s.execute();}
std::optional<Objective>SqliteAutonomyRepository::load_objective(ObjectiveId id){Statement s{database_,"SELECT title,desired_outcome,priority,status,created_at_ms FROM objectives WHERE id=?;"};s.bind(1,sid(id));if(!s.step())return std::nullopt;auto pr=priority_from_string(s.column_text(2));auto st=objective_status_from_string(s.column_text(3));if(!pr||!st)throw DatabaseError("invalid objective enum");Objective o;o.id=id;o.title=s.column_text(0);o.desired_outcome=s.column_text(1);o.priority=*pr;o.status=*st;o.created_at=from_unix_milliseconds(s.column_int64(4));Statement m{database_,"SELECT name,target_value,unit FROM objective_metrics WHERE objective_id=? ORDER BY position;"};m.bind(1,sid(id));while(m.step())o.success_metrics.push_back({m.column_text(0),m.column_double(1),m.column_text(2)});Statement c{database_,"SELECT value FROM objective_constraints WHERE objective_id=? ORDER BY position;"};c.bind(1,sid(id));while(c.step())o.constraints.push_back(c.column_text(0));Statement d{database_,"SELECT dependency_id FROM objective_dependencies WHERE objective_id=?;"};d.bind(1,sid(id));while(d.step())o.dependencies.push_back(static_cast<ObjectiveId>(d.column_int64(0)));return o;}
std::optional<Proposal>SqliteAutonomyRepository::load_proposal(ProposalId id){Statement s{database_,"SELECT objective_id,proposed_by,plan_name,risk,estimated_usd,estimated_compute_seconds,estimated_duration_seconds,expected_value,confidence,human_approval_required,status,created_at_ms FROM proposals WHERE id=?;"};s.bind(1,sid(id));if(!s.step())return std::nullopt;auto risk=risk_from_string(s.column_text(3));auto status=proposal_status_from_string(s.column_text(10));if(!risk||!status)throw DatabaseError("invalid proposal enum");Proposal p;p.id=id;p.objective_id=static_cast<ObjectiveId>(s.column_int64(0));p.proposed_by=s.column_text(1);p.plan.name=s.column_text(2);p.risk=*risk;p.cost.estimated_usd=s.column_double(4);p.cost.estimated_compute_seconds=s.column_double(5);p.cost.estimated_duration_seconds=s.column_double(6);p.expected_value=s.column_double(7);p.confidence=s.column_double(8);p.human_approval_required=s.column_int64(9)!=0;p.status=*status;p.created_at=from_unix_milliseconds(s.column_int64(11));Statement q{database_,"SELECT name,description,reversible FROM proposal_steps WHERE proposal_id=? ORDER BY position;"};q.bind(1,sid(id));while(q.step())p.plan.steps.push_back({q.column_text(0),q.column_text(1),q.column_int64(2)!=0});return p;}
std::optional<OperationRecord>SqliteAutonomyRepository::load_operation(OperationId id){Statement s{database_,"SELECT objective_id,proposal_id,agent_id,status,created_at_ms,started_at_ms,completed_at_ms,verification_passed,verification_confidence,failure_reason FROM operations WHERE id=?;"};s.bind(1,sid(id));if(!s.step())return std::nullopt;auto status=operation_status_from_string(s.column_text(3));if(!status)throw DatabaseError("invalid operation enum");OperationRecord o;o.id=id;o.objective_id=static_cast<ObjectiveId>(s.column_int64(0));o.proposal_id=static_cast<ProposalId>(s.column_int64(1));o.agent_id=s.column_text(2);o.status=*status;o.created_at=from_unix_milliseconds(s.column_int64(4));o.started_at=opt_time(s,5);o.completed_at=opt_time(s,6);o.verification.passed=s.column_int64(7)!=0;o.verification.confidence=s.column_double(8);o.failure_reason=s.column_text(9);Statement t{database_,"SELECT message FROM execution_traces WHERE operation_id=? ORDER BY position;"};t.bind(1,sid(id));while(t.step())o.execution_trace.push_back(t.column_text(0));Statement f{database_,"SELECT message FROM verification_findings WHERE operation_id=? ORDER BY position;"};f.bind(1,sid(id));while(f.step())o.verification.findings.push_back(f.column_text(0));Statement c{database_,"SELECT message FROM verification_corrections WHERE operation_id=? ORDER BY position;"};c.bind(1,sid(id));while(c.step())o.verification.corrections.push_back(c.column_text(0));return o;}
std::vector<Objective>SqliteAutonomyRepository::load_objectives(){std::vector<Objective>v;Statement s{database_,"SELECT id FROM objectives ORDER BY id;"};while(s.step())if(auto x=load_objective(static_cast<ObjectiveId>(s.column_int64(0))))v.push_back(std::move(*x));return v;}std::vector<Proposal>SqliteAutonomyRepository::load_proposals(){std::vector<Proposal>v;Statement s{database_,"SELECT id FROM proposals ORDER BY id;"};while(s.step())if(auto x=load_proposal(static_cast<ProposalId>(s.column_int64(0))))v.push_back(std::move(*x));return v;}std::vector<OperationRecord>SqliteAutonomyRepository::load_operations(){std::vector<OperationRecord>v;Statement s{database_,"SELECT id FROM operations ORDER BY id;"};while(s.step())if(auto x=load_operation(static_cast<OperationId>(s.column_int64(0))))v.push_back(std::move(*x));return v;}std::vector<AuditEvent>SqliteAutonomyRepository::load_audit_events(std::size_t limit){std::vector<AuditEvent>v;Statement s{database_,"SELECT id,event_type,entity_type,entity_id,actor,message,metadata_json,created_at_ms FROM audit_events ORDER BY id DESC LIMIT ?;"};s.bind(1,static_cast<std::int64_t>(limit));while(s.step()){AuditEvent e;e.id=static_cast<AuditEventId>(s.column_int64(0));e.event_type=s.column_text(1);e.entity_type=s.column_text(2);e.entity_id=static_cast<std::uint64_t>(s.column_int64(3));e.actor=s.column_text(4);e.message=s.column_text(5);e.metadata_json=s.column_text(6);e.created_at=from_unix_milliseconds(s.column_int64(7));v.push_back(std::move(e));}return v;}
}

